/**
 * @file feedbackQuizSchema.ts
 * @description
 * This file defines the formal JSON schema and structural contract for the Quiz Feedback Pipeline. 
 * Its primary responsibility is to enforce the presence of pedagogical metadata—specifically 
 * explanations and verbatim citations—within the structured output generated by the LLM. 
 * By defining a strict interface that includes the 'topicKey', 'explanation', and 'citation' fields, 
 * this schema ensures that the frontend remediation UI (StudentQuizSummary) receives all the data 
 * points required to guide a learner's recovery after an incorrect response. This file is 
 * critical to the sprint as it serves as the validation gate for the AI's response, preventing 
 * malformed data from entering the Yjs document state. It handles Multiple Choice, True/False, 
 * and Fill-in-the-Blank variants by wrapping them in a feedback-capable envelope, maintaining 
 * 100% consistency between the AI's "thought process" and the application's data requirements.
 */

// 1. Define the core feedback properties required for student remediation
const feedbackFields = {
  "topicKey": {
    "type": "string",
    "description": "The simplified token (e.g., A0, A1) from the reference dictionary provided in the prompt."
  },
  "explanation": {
    "type": "string",
    "description": "A 2-3 sentence pedagogical explanation of why the correct answer is right."
  },
  "citation": {
    "type": "object",
    "properties": {
      "text": { "type": "string", "description": "The exact verbatim quote from the study material context that proves the answer." },
    },
    "required": ["text"],
    "additionalProperties": false
  }
};

const baseRequiredFields = [ "topicKey", "explanation", "citation"];

// 2. Define the enriched Multiple Choice Schema
export const FeedbackMultipleChoiceSchema = {
  "name": "MultipleChoiceQuiz",
  "strict": true,
  "schema": {
    "type": "object",
    "properties": {
      "id": {
        "type": "string",
        "description": "Unique identifier for the quiz."
      },
      "title": {
        "type": "string",
        "description": "Title of the quiz."
      },
      "questions": {
        "type": "array",
        "description": "List of questions in the quiz.",
        "items": {
          "type": "object",
          "properties": {
            "id": {
              "type": "string",
              "description": "Unique identifier for each question."
            },
            "question": {
              "type": "string",
              "description": "The question text."
            },
            "options": {
              "type": "array",
              "description": "Multiple-choice options.",
              "items": {
                "type": "string"
              }
            },
            "correctAnswer": {
              "type": "string",
              "description": "Single correct answer."
            },
            ...feedbackFields
          },
          "required": [
            "id",
            "question",
            "options",
            "correctAnswer",
            ...baseRequiredFields
          ],
          "additionalProperties": false
        }
      }
    },
    "required": ["id", "title", "questions"],
    "additionalProperties": false
  }
};



